# Figures (data/viz/park_robin.json): each shows something real, with its source in the caption.
from robin_lib import FIGS
def blocks(nodes, edges, caption, flow=True):
    return {'type': 'blocks', 'nodes': [{'id': a, 'label': b, 'x': c, 'y': d, **({'color': e} if e else {})} for a, b, c, d, e in nodes], 'edges': [{'from': a, 'to': b, **({'label': c} if c else {})} for a, b, c in edges], 'flow': flow, 'caption': caption}
def bars(b, yl, cap, logy=False): return {'type': 'bars', 'bars': [{'label': l, 'value': v} for l, v in b], 'ylabel': yl, 'caption': cap, **({'logy': True} if logy else {})}
def table(cols, rows, cap): return {'type': 'table', 'cols': cols, 'rows': rows, 'caption': cap}
FIGS['robin'] = table(['Measurement', 'Value', 'Source'], [['Length', '12.5 to 14.0 cm', 'Wikipedia'], ['Mass', '16 to 22 g (adult mean ≈ 19 g)', 'Wikipedia; BTO'], ['Wingspan', '20 to 22 cm', 'Wikipedia'], ['Feathers drawn', '10 primaries, 9 secondaries (6 + 3 tertials), 12 tail', 'Pyle 2008']], 'The sizes used for the model. The proportions of the parts are drawn by eye; the feather counts are the published counts for passerines.')
FIGS['robin_prim'] = table(['Feather group', 'Number in a passerine wing or tail', 'Where it is attached'], [['Primaries', '10 per wing (outermost tiny; some families 9)', 'hand'], ['Secondaries', '9 per wing, including 3 tertials', 'forearm and elbow'], ['Tail feathers', '12 (6 pairs)', 'pygostyle']], 'Counts from Pyle 2008 (nine or ten functional primaries, nine secondaries including three tertials, twelve rectrices) and the Flight feather and Passerine pages.')
FIGS['robin_sec'] = FIGS['robin_prim']; FIGS['robin_tail'] = FIGS['robin_prim']
FIGS['robin_temperature'] = bars([('resting phase', 38.54), ('active phase', 41.02), ('high activity', 43.85)], 'body temperature (°C)', 'Mean body temperatures of birds in general in the three phases (Prinzinger, Pressmar and Schleucher 1991: 203, 724 and 74 birds). Passerines run slightly high in the active phase.')
FIGS['robin_lifespan'] = bars([('average life expectancy', 1.1), ('typical, if it reaches breeding age', 2), ('ringing record (BTO)', 8.4), ('longer record quoted by Wikipedia', 19)], 'years', 'How long robins live: the average (Wikipedia) and the typical age of breeders and the British ringing record, 8 years 4 months 30 days ≈ 8.4 years (BTO). The two sources disagree on the record.')
FIGS['robin_night_song'] = bars([('daytime noise at day-only sites', 53), ('daytime noise at night-singing sites', 63)], 'average daytime noise (dB)', 'Sheffield, 121 locations: robins sang at night at 18 of the 67 sites where they sang by day, and those sites were louder by day (≈ 63 dB against ≈ 53 dB). Fuller, Warren and Gaston 2007.')
FIGS['robin_territory'] = blocks([('a', 'Stuffed robin placed in a territory', 15, 25, None), ('b', 'Bundle of red feathers alone', 15, 75, None), ('c', 'The resident robin attacks', 70, 50, 'orange')], [('a', 'c', 'attacked'), ('b', 'c', 'attacked, in some birds')], 'David Lack\'s experiments at Dartington, as reported in The Life of the Robin: red feathers alone could release an attack (Great British Life).')
FIGS['robin_migration'] = blocks([('s', 'Scandinavia and Russia', 12, 20, None), ('b', 'Britain and western Europe', 62, 20, 'green'), ('r', 'British and Irish robins: mostly resident', 62, 55, None), ('m', 'A small minority, usually females', 12, 80, None), ('e', 'Southern Europe, some to Spain', 62, 85, 'orange')], [('s', 'b', 'winter'), ('m', 'e', 'winter')], 'Where robins go (Wikipedia, European robin; BTO).')
FIGS['robin_dinosaur'] = blocks([('t', 'Theropod dinosaurs', 12, 20, None), ('m', 'Maniraptorans: many with feathers', 45, 50, 'orange'), ('a', 'Archaeopteryx, ≈ 155 million years ago', 78, 20, None), ('b', 'Living birds, over 11,000 species', 78, 80, 'green')], [('t', 'm', None), ('m', 'a', None), ('m', 'b', None)], 'Birds are maniraptoran theropod dinosaurs (Wikipedia: Origin of birds; Bird). The order of events within the group is debated.')
FIGS['robin_compass'] = blocks([('l', 'Light reaches the retina', 8, 30, None), ('c', 'Cryptochrome 4 with FAD', 32, 30, None), ('r', 'Electron jumps along four tryptophans: a radical pair forms', 58, 30, 'orange'), ('f', 'Earth\'s field might change how long the pair lasts', 58, 75, 'orange'), ('s', 'A signal to the brain? (not shown)', 85, 55, None)], [('l', 'c', None), ('c', 'r', 'in vitro'), ('r', 'f', 'hypothesis'), ('f', 's', 'unproven')], 'The radical-pair hypothesis. The first steps are measured in purified robin cryptochrome 4 (Xu et al. 2021; Wong et al. 2021); the last two are not shown in a living bird.')
FIGS['robin_breathing'] = blocks([('t', 'Breathe in: windpipe', 8, 50, None), ('p', 'Rear air sacs', 32, 50, 'blue'), ('l', 'Lung tubes (parabronchi)', 58, 50, 'green'), ('a', 'Front air sacs', 82, 50, 'blue'), ('o', 'Out through the windpipe', 82, 15, None)], [('t', 'p', 'in'), ('p', 'l', None), ('l', 'a', None), ('a', 'o', 'out')], 'The one-way route of air through a bird (from the tracer-gas study of zebra finches and blackbirds). A breath stays in for two breath cycles.')
FIGS['robin_lungs'] = FIGS['robin_breathing']; FIGS['robin_air_sacs'] = table(['Air-sac group', 'Sacs', 'Role'], [['Front (anterior)', 'interclavicular, cervical, anterior thoracic', 'empty through the windpipe'], ['Rear (posterior)', 'posterior thoracic, abdominal', 'receive most of the breathed-in air']], 'The two functional groups of air sacs (the tracer-gas study). Nine sacs are usual in birds; descriptions of passerines differ (Wikipedia gives seven).')
FIGS['robin_flight'] = blocks([('d', 'Downstroke: wing pushes air down', 12, 25, None), ('l', 'Lift (up) and thrust (forward)', 55, 25, 'green'), ('u', 'Upstroke: wing folded a little', 12, 75, None), ('a', 'Alula keeps air attached at low speed', 55, 75, None)], [('d', 'l', 'most of the force'), ('u', 'l', 'some thrust'), ('a', 'l', 'when landing')], 'What the wing does in a beat (Wikipedia: Bird flight). The lift comes from air flowing over the wing, not only from pushing down.')
FIGS['robin_song'] = blocks([('lg', 'Air from the lungs', 8, 50, None), ('b', 'Two bronchi', 30, 50, None), ('m', 'Membranes vibrate: left and right sides tuned separately', 58, 50, 'orange'), ('t', 'Windpipe and mouth shape the sound', 85, 50, None)], [('lg', 'b', None), ('b', 'm', None), ('m', 't', None)], 'Where the song is made. The two sides of the syrinx can be controlled separately (Suthers 1990, cited by Wikipedia: Syrinx).')
FIGS['robin_syrinx'] = FIGS['robin_song']
FIGS['robin_supracoracoideus'] = blocks([('m', 'Supracoracoideus on the breast', 10, 70, None), ('t', 'Tendon', 35, 70, None), ('c', 'Triosseal canal: the pulley', 60, 30, 'orange'), ('h', 'Top of the humerus: wing goes up', 85, 70, 'green')], [('m', 't', 'contracts'), ('t', 'c', 'pulled down'), ('c', 'h', 'turned up')], 'The pulley that lets a breast muscle lift the wing.')
FIGS['robin_cervical'] = bars([('human', 7), ('songbirds (nearly all)', 14), ('swans (the most)', 25)], 'neck vertebrae', 'Neck vertebrae: 7 in a person, 14 in all but 2 of 159 songbirds (Webster and Goff) and as many as 25 in some swans (Wikipedia, Bird anatomy).')
FIGS['robin_leg_toes'] = table(['Toe', 'Points', 'Bones'], [['I (hind toe)', 'back', '2'], ['II (inner)', 'forward', '3'], ['III (middle)', 'forward', '4'], ['IV (outer)', 'forward', '5']], 'Toe bones in a typical perching bird (Wikipedia, Bird feet and legs).')
FIGS['robin_toe_bones'] = FIGS['robin_leg_toes']
FIGS['robin_keratin'] = blocks([('c', 'Cysteine', 10, 50, None), ('s', 'Cystine: two cysteines joined by a sulfur bridge', 40, 50, 'orange'), ('k', 'Beta-keratin sheets', 70, 25, None), ('f', 'Feather, bill, claw', 88, 75, 'green')], [('c', 's', 'oxidation'), ('s', 'k', 'cross-link'), ('k', 'f', None)], 'How keratin is held together. Keratin itself is not in the molecule data; cysteine and cystine are.')
FIGS['robin_pigment'] = blocks([('t', 'Tyrosine', 10, 50, None), ('d', 'L-DOPA', 35, 50, 'orange'), ('m', 'Melanin', 60, 50, 'green'), ('g', 'Pigment granules in the feather', 85, 50, None)], [('t', 'd', None), ('d', 'm', 'more steps'), ('m', 'g', None)], 'The route to melanin. Whether the orange breast is melanin-based is not settled (Delhey et al. 2010 classed it so without a chemical test).')
FIGS['robin_heart'] = blocks([('b', 'Body', 8, 50, None), ('ra', 'Right atrium', 28, 20, 'blue'), ('rv', 'Right ventricle', 50, 20, 'blue'), ('lu', 'Lungs', 72, 20, None), ('la', 'Left atrium', 72, 80, 'orange'), ('lv', 'Left ventricle', 40, 80, 'orange')], [('b', 'ra', 'oxygen-poor'), ('ra', 'rv', None), ('rv', 'lu', None), ('lu', 'la', 'oxygen-rich'), ('la', 'lv', None), ('lv', 'b', None)], 'The two circuits of a four-chambered heart.')
FIGS['robin_wing'] = table(['', 'Human arm', 'Robin wing'], [['Upper arm', 'humerus', 'humerus'], ['Forearm', 'radius and ulna', 'radius and ulna'], ['Wrist and palm', '8 wrist bones and 5 palm bones', 'fused into one hand bone'], ['Fingers', '5', '3 (identity debated)']], 'The wing is an arm. The human column is standard anatomy; the bird column is from Wikipedia (Bird anatomy; Origin of birds).')
FIGS['robin_carpometacarpus'] = FIGS['robin_wing']; FIGS['robin_humerus'] = FIGS['robin_wing']
FIGS['robin_feather_scene'] = bars([('barbule spacing, closest (µm)', 8), ('as drawn (µm)', 12), ('barbule spacing, widest (µm)', 16)], 'micrometres', 'The only published size in the scene: barbules on flight feathers of birds from a hummingbird to a condor are 8 to 16 micrometres apart (J. R. Soc. Interface 2025).')
FIGS['robin_barbule'] = FIGS['robin_feather_scene']
FIGS['robin_hollow_bones'] = table(['Bird', 'Hollow, air-filled bones?'], [['Robin and most flying birds', 'many'], ['Ostrich, emu', 'some (femur; emu neck)'], ['Penguins, loons, puffins, kiwis', 'none']], 'Which birds have pneumatic bones (Wikipedia, Bird anatomy). A bird\'s plumage can weigh two or three times as much as its skeleton (Wikipedia, Feather).')
FIGS['robin_scleral_ring'] = bars([('fewest plates', 12), ('most common', 14), ('most plates', 18)], 'plates per ring', 'Scleral ossicles in birds: most rings have 12 to 18 plates, 14 the most common (Wikipedia, Scleral ring).')
FIGS['robin_pecten'] = bars([('fewest', 5), ('most', 30)], 'pleats', 'The pleated pecten has 5 to 30 pleats overall (Wikipedia, Pecten oculi).')
FIGS['robin_gizzard'] = bars([('muscular bands in the gizzard', 4)], 'bands', 'The gizzard is made of four muscular bands (Wikipedia, Bird anatomy).')
FIGS['robin_pygostyle'] = bars([('fewest counted', 4), ('most counted', 10)], 'fused tail vertebrae', 'The pygostyle is formed from the last four caudal vertebrae, though some sources say up to ten (Wikipedia, Bird anatomy).')
FIGS['robin_synsacrum'] = bars([('thoracic', 1), ('lumbar', 6), ('sacral', 2), ('sacro-caudal', 5)], 'vertebrae fused', 'Vertebrae in the synsacrum of birds in general (Wikipedia, Bird anatomy): 1 + 6 + 2 + 5 = 14.')
